static char *call(const AgentConfig *cfg,const char *input,int expected){char *out=NULL;size_t n;FILE *stream=open_memstream(&out,&n);CHECK(stream);int rc=agent_dispatch(cfg,input,strlen(input),stream);CHECK(!fclose(stream));if(rc!=expected)fprintf(stderr,"response %s\n",out);CHECK(rc==expected);Json j;CHECK(json_parse(&j,out,n));return out;}
static void file(const char *path,const char *value){FILE *out=fopen(path,"w");CHECK(out);CHECK(fputs(value,out)>=0);CHECK(!fclose(out));}
static void assert_file(const char *path,const char *value){FILE *in=fopen(path,"r");CHECK(in);char data[128];size_t n=fread(data,1,sizeof(data)-1,in);data[n]=0;CHECK(!fclose(in));CHECK(!strcmp(data,value));}
static char *field(const char *out,const char *key){Json j;CHECK(json_parse(&j,out,strlen(out)));char *value=json_string(&j,json_get(&j,0,key));CHECK(value);return value;}
static char *operation(const char *op,const char *id,const char *name){char *out=NULL;size_t n;FILE *stream=open_memstream(&out,&n);CHECK(stream);fprintf(stream,"{\"contract_version\":1,\"op\":\"%s\",\"%s\":\"%s\"",op,!strcmp(op,"undo_plan_create")?"source_plan_id":"plan_id",id);if(name)fprintf(stream,",\"operation_id\":\"%s\",\"plan_revision\":1",name);fputc('}',stream);CHECK(!fclose(stream));return out;}
static void approve(const AgentConfig *cfg,const char *plan,const char *name){char *input=operation("plan_approve",plan,name),*out=call(cfg,input,0);CHECK(strstr(out,"\"approved\":true"));free(input);free(out);}
static char *copy(const AgentConfig *cfg,const char *target,const char *name){char source[2048],version[65],identity[65],metadata[256],input[2048];snprintf(source,sizeof(source),"%s/source.txt",cfg->action_root);struct stat info;CHECK(!stat(source,&info));
#ifdef __APPLE__
    long nanos=info.st_mtimespec.tv_nsec;
#else
    long nanos=info.st_mtim.tv_nsec;
#endif
    int n=snprintf(metadata,sizeof(metadata),"file-identity-v1:%llu:%llu:%llu:%lld:%ld",(unsigned long long)info.st_dev,(unsigned long long)info.st_ino,(unsigned long long)info.st_size,(long long)info.st_mtime,nanos);hash_bytes(metadata,(size_t)n,identity);hash_bytes("code 7319",9,version);snprintf(input,sizeof(input),"{\"contract_version\":1,\"op\":\"plan_create\",\"operation_id\":\"%s-create\",\"action\":\"copy\",\"host_id\":\"local-endpoint\",\"files\":[{\"source\":\"source.txt\",\"destination\":\"%s\",\"version\":\"%s\",\"file_identity\":\"%s\"}]}",name,target,version,identity);char *out=call(cfg,input,0),*plan=field(out,"plan_id");free(out);char op[128];snprintf(op,sizeof(op),"%s-approve",name);approve(cfg,plan,op);snprintf(op,sizeof(op),"%s-copy",name);char *request=operation("plan_execute",plan,op);out=call(cfg,request,0);CHECK(strstr(out,"\"copied_items\":1"));free(request);free(out);return plan;}
static char *inverse(const AgentConfig *cfg,const char *source_plan,const char *name){char *input=operation("undo_plan_create",source_plan,name),*out=call(cfg,input,0),*plan=field(out,"plan_id");CHECK(strstr(out,"undo_copy"));free(input);free(out);return plan;}
static pid_t worker(const char *exe,const char *state,const char *root,const char *plan,const char *name){char *args[]={(char*)exe,"--worker",(char*)state,(char*)root,(char*)plan,(char*)name,NULL};pid_t pid;CHECK(!posix_spawnp(&pid,exe,NULL,NULL,args,environ));return pid;}
static void ready(const char *marker){int found=0;for(int i=0;i<500;i++){if(!access(marker,F_OK)){found=1;break;}struct timespec delay={0,10000000};nanosleep(&delay,NULL);}CHECK(found);}
